import os
import tempfile
from functools import wraps
from datetime import datetime
from taf.ul.oam.selenium_core.common import PagePart


class Debug(PagePart):
    def __init__(self, driver, debug_dir=None):
        if debug_dir is None:
            self._debug_dir = tempfile.mkdtemp(prefix="taf_selenium_megazone_debug")
        else:
            self._debug_dir = debug_dir
        if not os.path.exists(self._debug_dir):
            os.makedirs(self._debug_dir)
        super(Debug, self).__init__(driver)

    def save_screenshot(self, filename):
        self._driver.save_screenshot('{}/{}_{}.png'.
                                     format(self._debug_dir, filename, datetime.now().strftime("%Y%m%d_%H%M%S")))


def catch_interface_exception(func):
    """
    Method to catch exception and save screenshot if function raises an error
    """
    @wraps(func)
    def interface_func(*args, **kwargs):
        try:
            outcome = func(*args, **kwargs)
        except Exception:
            instance = args[0]
            Debug(instance._driver, instance._debug_dir).save_screenshot('{}'.format(func.__name__))
            raise
        return outcome
    return interface_func
